-- ============================================
-- LUMA — Thème 4 : LONG 2/3 x4 — Un voyage avec imprévus en cascade
-- ============================================


update scenarios set content = '{"characters": {"taxi_driver": "le chauffeur de taxi", "hotel_staff": "le personnel de l''hôtel", "receptionist": "la réceptionniste"}, "start_node": "n1", "nodes": {"n1": {"speaker": "taxi_driver", "text": "Where to? I don''t think I know that hotel name, actually.", "text_fr": "Vous allez où ? Je pense pas connaître ce nom d''hôtel, en fait.", "choices": [{"text": "Let me show you the address on my phone.", "text_fr": "Laissez-moi vous montrer l''adresse sur mon téléphone.", "next": "n2"}, {"text": "It''s near the old cathedral, if that helps.", "text_fr": "C''est près de la vieille cathédrale, si ça aide.", "next": "n2b"}]}, "n2": {"speaker": "taxi_driver", "text": "Ah, I see it now, got it. Let''s go.", "text_fr": "Ah, je le vois maintenant, compris. On y va.", "choices": [{"text": "Great, thank you.", "text_fr": "Super, merci.", "next": "n3"}]}, "n2b": {"speaker": "taxi_driver", "text": "Oh, that helps a lot, I know that area well.", "text_fr": "Oh, ça aide beaucoup, je connais bien ce quartier.", "choices": [{"text": "Perfect, let''s head there then.", "text_fr": "Parfait, allons-y alors.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(Twenty minutes later, you arrive, but the hotel looks closed and dark.)", "text_fr": "(Vingt minutes plus tard, vous arrivez, mais l''hôtel semble fermé et dans le noir.)", "choices": [{"text": "(Try calling the hotel to check what''s going on.)", "text_fr": "(Essaie d''appeler l''hôtel pour vérifier ce qui se passe.)", "next": "n4"}, {"text": "(Knock on the front door to see if anyone''s there.)", "text_fr": "(Frappe à la porte d''entrée pour voir si quelqu''un est là.)", "next": "n4b"}]}, "n4": {"speaker": "hotel_staff", "text": "(On the phone) I''m so sorry, we had a pipe burst and had to close temporarily!", "text_fr": "(Au téléphone) Je suis vraiment désolé, on a eu une fuite de tuyau et on a dû fermer temporairement !", "choices": [{"text": "Oh no — do you have any other location I could go to?", "text_fr": "Oh non — vous avez un autre établissement où je pourrais aller ?", "next": "n5"}]}, "n4b": {"speaker": "hotel_staff", "text": "(Opens the door partially) I''m sorry, we''re closed due to a burst pipe!", "text_fr": "(Ouvre la porte partiellement) Désolé, on est fermés à cause d''une fuite de tuyau !", "choices": [{"text": "That''s unfortunate — can you help me find another hotel nearby?", "text_fr": "C''est fâcheux — vous pouvez m''aider à trouver un autre hôtel à proximité ?", "next": "n5"}]}, "n5": {"speaker": "hotel_staff", "text": "Yes, we''ve arranged rooms at a sister hotel a few blocks away, no extra charge.", "text_fr": "Oui, on a arrangé des chambres dans un hôtel partenaire à quelques rues, sans frais supplémentaire.", "choices": [{"text": "That''s a relief, thank you for sorting that out.", "text_fr": "Ça soulage, merci d''avoir arrangé ça.", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(You take a short walk to the sister hotel and check in.)", "text_fr": "(Vous marchez un peu jusqu''à l''hôtel partenaire et vous enregistrez.)", "choices": [{"text": "(Try paying with your card at check-in.)", "text_fr": "(Essaie de payer avec ta carte à l''enregistrement.)", "next": "n7"}]}, "n7": {"speaker": "receptionist", "text": "I''m sorry, your card seems to be declining. Do you have another payment method?", "text_fr": "Je suis désolée, votre carte semble refusée. Vous avez un autre moyen de paiement ?", "choices": [{"text": "Let me try a different card.", "text_fr": "Laissez-moi essayer une autre carte.", "next": "n8"}, {"text": "Could I call my bank first to figure out what''s happening?", "text_fr": "Je pourrais appeler ma banque d''abord pour comprendre ce qui se passe ?", "next": "n8b"}]}, "n8": {"speaker": "receptionist", "text": "(Tries the new card) Great, this one worked perfectly.", "text_fr": "(Essaie la nouvelle carte) Super, celle-ci a fonctionné parfaitement.", "choices": [{"text": "Phew, what a relief. Thank you for your patience.", "text_fr": "Ouf, quel soulagement. Merci pour votre patience.", "next": "n9"}]}, "n8b": {"speaker": "you_thought", "text": "(After a quick call, you learn the bank flagged the charge as suspicious due to the new country.)", "text_fr": "(Après un appel rapide, vous apprenez que la banque a signalé la transaction comme suspecte à cause du nouveau pays.)", "choices": [{"text": "(Confirm the charge with the bank and try the card again.)", "text_fr": "(Confirme la transaction avec la banque et réessaie la carte.)", "next": "n9"}]}, "n9": {"speaker": "receptionist", "text": "All sorted now! Here are your room keys.", "text_fr": "Tout est réglé maintenant ! Voici vos clés de chambre.", "choices": [{"text": "Thank you so much for your help through all of this.", "text_fr": "Merci beaucoup pour votre aide à travers tout ça.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(Finally in your room, exhausted, you realize your phone charger is missing from your bag.)", "text_fr": "(Enfin dans votre chambre, épuisé, vous réalisez que votre chargeur de téléphone manque de votre sac.)", "choices": [{"text": "(Ask the front desk if they have a charger to lend.)", "text_fr": "(Demande à la réception s''ils ont un chargeur à prêter.)", "next": "n11"}, {"text": "(Decide it can wait until tomorrow and just go to sleep.)", "text_fr": "(Décide que ça peut attendre demain et va juste te coucher.)", "next": "n11b"}]}, "n11": {"speaker": "receptionist", "text": "Of course, we have a few at the front desk you can borrow.", "text_fr": "Bien sûr, on en a quelques-uns à la réception que vous pouvez emprunter.", "choices": [{"text": "Thank you, that''s exactly what I needed after today.", "text_fr": "Merci, c''est exactement ce dont j''avais besoin après aujourd''hui.", "next": "end_resolved"}]}, "n11b": {"speaker": "you_thought", "text": "(You decide the day''s chaos is finally over, and drift off to sleep.)", "text_fr": "(Vous décidez que le chaos de la journée est enfin terminé, et vous vous endormez.)", "choices": [{"text": "(Fall asleep, relieved the day is finally done.)", "text_fr": "(T''endors, soulagé que la journée soit enfin finie.)", "next": "end_resolved"}]}, "end_resolved": {"speaker": "you_thought", "text": "(Despite the chain of mishaps, everything worked out by the end of the day.)", "text_fr": "(Malgré la cascade de mésaventures, tout s''est arrangé à la fin de la journée.)", "end": true, "ending_label": "Imprévus en cascade surmontés avec calme 🧳🏨✅"}}}'::jsonb, is_playable = true
where title = 'Un voyage avec imprévus en cascade'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
